import{_ as p,a0 as l,w as o,s as u,I as a,x as s,a1 as t,A as e,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"如何从 Linux 终端发送桌面通知与提醒 | LCTT x X-CMD","titleTemplate":false,"description":"如何从 Linux 终端发送桌面通知与提醒 | LCTT (202207) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何从 Linux 终端发送桌面通知与提醒 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何从 Linux 终端发送桌面通知与提醒 | LCTT (202207) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202207/20220106 Send desktop notifications and reminders from Linux terminal","title":"如何从 Linux 终端发送桌面通知与提醒","tag":"202207","desc":""},"relativePath":"202207/20220106 Send desktop notifications and reminders from Linux terminal.md","filePath":"[post].md"}'),r={name:"202207/20220106 Send desktop notifications and reminders from Linux terminal.md"};function c(h,n,f,m,g,k){const i=l("Link");return o(),u("div",null,[n[26]||(n[26]=a("h1",{id:"如何从-linux-终端发送桌面通知与提醒",tabindex:"-1"},[s("如何从 Linux 终端发送桌面通知与提醒 "),a("a",{class:"header-anchor",href:"#如何从-linux-终端发送桌面通知与提醒","aria-label":"Permalink to “如何从 Linux 终端发送桌面通知与提醒”"},"​")],-1)),n[27]||(n[27]=a("blockquote",null,[a("p",null,"这篇教程演示如何使用脚本命令来发送自己的桌面通知与提醒。")],-1)),n[28]||(n[28]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202207/14/145103vawkhy6w506thy6h.jpg",alt:""})],-1)),n[29]||(n[29]=a("p",null,"有时候，来自脚本的视觉回馈是很有用的。例如，当一个脚本或计划任务完成时，一个长期运行的构建任务失败时，或者当脚本执行中出现了紧急问题时。桌面应用程序可以通过弹出通知来做到这一点，但脚本也可以做到这一点！你可以使用脚本命令来给自己发送桌面通知与提醒。",-1)),n[30]||(n[30]=a("p",null,[a("img",{src:"https://opensource.com/sites/default/files/buyeggs.png",alt:"Example notification",title:"Example notification"})],-1)),a("p",null,[n[1]||(n[1]=s("下面的代码是在 Linux 上编写和测试的。它也可以在 macOS 上运行，只需花点功夫。请参见最后一节 ",-1)),t(i,{href:"https://opensource.com/article/22/1/linux-desktop-notifications/#script-notifications-on-macOS"},{default:e(()=>[...n[0]||(n[0]=[s("提示与技巧",-1)])]),_:1}),n[2]||(n[2]=s("。",-1))]),n[31]||(n[31]=a("h3",{id:"从-linux-终端发送通知",tabindex:"-1"},[s("从 Linux 终端发送通知 "),a("a",{class:"header-anchor",href:"#从-linux-终端发送通知","aria-label":"Permalink to “从 Linux 终端发送通知”"},"​")],-1)),a("p",null,[n[4]||(n[4]=s("要从 Linux 终端发送通知，请使用 ",-1)),t(i,{href:"https://manpages.ubuntu.com/manpages/xenial/man1/notify-send.1.html"},{default:e(()=>[...n[3]||(n[3]=[s("notify-send",-1)])]),_:1}),n[5]||(n[5]=s(" 命令。运行 ",-1)),n[6]||(n[6]=a("code",null,"which notify-send",-1)),n[7]||(n[7]=s(" 命令来查看它是否在于你的系统中。如果没有，请使用包管理器来安装它。",-1))]),n[32]||(n[32]=d(`<p>在 Fedora 上，输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install notify-send</span></span></code></pre></div><p>在基于 Debian 的发行版上，输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install notify-send</span></span></code></pre></div><p>几个简单的通知示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ notify-send &quot;Dinner ready!&quot;</span></span>
<span class="line"><span>$ notify-send &quot;Tip of the Day&quot; &quot;How about a nap?&quot;</span></span></code></pre></div><p>你可以用紧急程度、自定义图标等选项来自定义通知。过 <code>man notify-send</code> 了解更多。你也可以在通知正文中使用一小组 HTML 标记，以使消息有一个棒的视觉感受。最重要的是，URL 被呈现为可点击的。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ notify-send -u critical \\</span></span>
<span class="line"><span>  &quot;Build failed!&quot; \\</span></span>
<span class="line"><span>  &quot;There were &lt;b&gt;123&lt;/b&gt; errors. Click here to see the results: http://buildserver/latest&quot;</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/buildfail.png" alt="Build fail notification" title="Build fail notification"></p><p>发送的通知会被桌面环境接收，并像其他通知一样显示。它们将具有相同的外观、交互和行为。</p><h3 id="将-notify-send-与-at-结合使用" tabindex="-1">将 notify-send 与 at 结合使用 <a class="header-anchor" href="#将-notify-send-与-at-结合使用" aria-label="Permalink to “将 notify-send 与 at 结合使用”">​</a></h3><p>计划任务通常被用来定期安排命令。<code>at</code> 命令安排在一个指定的时间执行一条命令。如果你像这样运行它，它会以交互模式启动，你可以在其中输入要在指定时间执行的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ at 12:00</span></span></code></pre></div><p>这对脚本来说并不有用。幸运的是 <code>at</code> 接受来自标准输入的参数，所以我们可以这样使用它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;npm run build&quot; | at now + 1 minute</span></span>
<span class="line"><span>$ echo &quot;backup-db&quot; | at 13:00</span></span></code></pre></div><p>有许多指定时间的方法。 从绝对时间，如 <code>10:00</code>，到相对时间，如 <code>now + 2 hours</code> ，再特殊时间，如<code>noon</code> 或 <code>midnight</code>。我们可以把它和 <code>notify-send</code> 结合起来，在未来的某个时间向自己发送提醒。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;notify-send &#39;Stop it and go home now?&#39; &#39;Enough work for today.&#39; -u critical&quot; | at now</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/stop-it.png" alt="Stop for the day notification" title="Stop for the day notification"></p><h3 id="提醒的命令" tabindex="-1">提醒的命令 <a class="header-anchor" href="#提醒的命令" aria-label="Permalink to “提醒的命令”">​</a></h3><p>现在，建立一个自定义的 Bash 命令来给自己发送提醒信息。像这样简单且人性化的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ remind &quot;I&#39;m still here&quot; now</span></span>
<span class="line"><span>$ remind &quot;Time to wake up!&quot; in 5 minutes</span></span>
<span class="line"><span>$ remind &quot;Dinner&quot; in 1 hour</span></span>
<span class="line"><span>$ remind &quot;Take a break&quot; at noon</span></span>
<span class="line"><span>$ remind &quot;It&#39;s Friday pints time!&quot; at 17:00</span></span></code></pre></div><p>这比 Alexa 更好！该怎样做？</p><p>请看下面的代码。它定义了一个名为 <code>remind</code> 的函数，它支持上述语法。实际工作是在最后两行完成的。其余的部分负责显示帮助信息、参数校验等，这与任何大型应用程序中有用的代码与必要的白噪声的比例大致相同。</p><p>把代码保存在某个地方，例如，在 <code>~/bin/remind</code> 文件中，并在你的 <code>.bashrc</code> 配置文件写入该函数，以便在你登录时加载它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ source ~/bin/remind</span></span></code></pre></div><p>重新打开终端，然后输入 <code>remind</code> 来查看语法。尽情享受吧！</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/usr/bin/env bash</span></span>
<span class="line"><span>function remind () {</span></span>
<span class="line"><span>  local COUNT=&quot;$#&quot;</span></span>
<span class="line"><span>  local COMMAND=&quot;$1&quot;</span></span>
<span class="line"><span>  local MESSAGE=&quot;$1&quot;</span></span>
<span class="line"><span>  local OP=&quot;$2&quot;</span></span>
<span class="line"><span>  shift 2</span></span>
<span class="line"><span>  local WHEN=&quot;$@&quot;</span></span>
<span class="line"><span>  # Display help if no parameters or help command</span></span>
<span class="line"><span>  if [[ $COUNT -eq 0 || &quot;$COMMAND&quot; == &quot;help&quot; || &quot;$COMMAND&quot; == &quot;--help&quot; || &quot;$COMMAND&quot; == &quot;-h&quot; ]]; then</span></span>
<span class="line"><span>    echo &quot;COMMAND&quot;</span></span>
<span class="line"><span>    echo &quot;    remind &amp;lt;message&amp;gt; &amp;lt;time&amp;gt;&quot;</span></span>
<span class="line"><span>    echo &quot;    remind &amp;lt;command&amp;gt;&quot;</span></span>
<span class="line"><span>    echo</span></span>
<span class="line"><span>    echo &quot;DESCRIPTION&quot;</span></span>
<span class="line"><span>    echo &quot;    Displays notification at specified time&quot;</span></span>
<span class="line"><span>    echo</span></span>
<span class="line"><span>    echo &quot;EXAMPLES&quot;</span></span>
<span class="line"><span>    echo &#39;    remind &quot;Hi there&quot; now&#39;</span></span>
<span class="line"><span>    echo &#39;    remind &quot;Time to wake up&quot; in 5 minutes&#39;</span></span>
<span class="line"><span>    echo &#39;    remind &quot;Dinner&quot; in 1 hour&#39;</span></span>
<span class="line"><span>    echo &#39;    remind &quot;Take a break&quot; at noon&#39;</span></span>
<span class="line"><span>    echo &#39;    remind &quot;Are you ready?&quot; at 13:00&#39;</span></span>
<span class="line"><span>    echo &#39;    remind list&#39;</span></span>
<span class="line"><span>    echo &#39;    remind clear&#39;</span></span>
<span class="line"><span>    echo &#39;    remind help&#39;</span></span>
<span class="line"><span>    echo</span></span>
<span class="line"><span>    return</span></span>
<span class="line"><span>  fi</span></span>
<span class="line"><span>  # Check presence of AT command</span></span>
<span class="line"><span>  if ! which at &amp;gt;/dev/null; then</span></span>
<span class="line"><span>    echo &quot;remind: AT utility is required but not installed on your system. Install it with your package manager of choice, for example &#39;sudo apt install at&#39;.&quot;</span></span>
<span class="line"><span>    return</span></span>
<span class="line"><span>  fi</span></span>
<span class="line"><span>  # Run commands: list, clear</span></span>
<span class="line"><span>  if [[ $COUNT -eq 1 ]]; then</span></span>
<span class="line"><span>    if [[ &quot;$COMMAND&quot; == &quot;list&quot; ]]; then</span></span>
<span class="line"><span>      at -l</span></span>
<span class="line"><span>    elif [[ &quot;$COMMAND&quot; == &quot;clear&quot; ]]; then</span></span>
<span class="line"><span>      at -r $(atq | cut -f1)</span></span>
<span class="line"><span>    else</span></span>
<span class="line"><span>      echo &quot;remind: unknown command $COMMAND. Type &#39;remind&#39; without any parameters to see syntax.&quot;</span></span>
<span class="line"><span>    fi</span></span>
<span class="line"><span>    return</span></span>
<span class="line"><span>  fi</span></span>
<span class="line"><span>  # Determine time of notification</span></span>
<span class="line"><span>  if [[ &quot;$OP&quot; == &quot;in&quot; ]]; then</span></span>
<span class="line"><span>    local TIME=&quot;now + $WHEN&quot;</span></span>
<span class="line"><span>  elif [[ &quot;$OP&quot; == &quot;at&quot; ]]; then</span></span>
<span class="line"><span>    local TIME=&quot;$WHEN&quot;</span></span>
<span class="line"><span>  elif [[ &quot;$OP&quot; == &quot;now&quot; ]]; then</span></span>
<span class="line"><span>    local TIME=&quot;now&quot;</span></span>
<span class="line"><span>  else</span></span>
<span class="line"><span>    echo &quot;remind: invalid time operator $OP&quot;</span></span>
<span class="line"><span>    return</span></span>
<span class="line"><span>  fi</span></span>
<span class="line"><span>  # Schedule the notification</span></span>
<span class="line"><span>  echo &quot;notify-send &#39;$MESSAGE&#39; &#39;Reminder&#39; -u critical&quot; | at $TIME 2&amp;gt;/dev/null</span></span>
<span class="line"><span>  echo &quot;Notification scheduled at $TIME&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="简单的提醒" tabindex="-1">简单的提醒 <a class="header-anchor" href="#简单的提醒" aria-label="Permalink to “简单的提醒”">​</a></h3><p>通过这几个简单的开源命令，你可以将你自己的脚本、应用程序和任务与你的桌面结合起来。试一试吧！</p><hr><p>（文内图片来自 Tomasz Waraksa, CC BY-SA 4.0）</p>`,31)),a("p",null,[n[9]||(n[9]=s("本文经作者许可改编自 ",-1)),t(i,{href:"https://letsdebug.it/post/30-linux-desktop-notifications/"},{default:e(()=>[...n[8]||(n[8]=[s("原文",-1)])]),_:1}),n[10]||(n[10]=s("。",-1))]),n[33]||(n[33]=a("hr",null,null,-1)),a("p",null,[n[12]||(n[12]=s("via: ",-1)),t(i,{href:"https://opensource.com/article/22/1/linux-desktop-notifications"},{default:e(()=>[...n[11]||(n[11]=[s("https://opensource.com/article/22/1/linux-desktop-notifications",-1)])]),_:1})]),a("p",null,[n[17]||(n[17]=s("作者：",-1)),t(i,{href:"https://opensource.com/users/tomasz"},{default:e(()=>[...n[13]||(n[13]=[s("Tomasz Waraksa",-1)])]),_:1}),n[18]||(n[18]=s(" 选题：",-1)),t(i,{href:"https://github.com/lujun9972"},{default:e(()=>[...n[14]||(n[14]=[s("lujun9972",-1)])]),_:1}),n[19]||(n[19]=s(" 译者：",-1)),t(i,{href:"https://github.com/mcfd"},{default:e(()=>[...n[15]||(n[15]=[s("mcfd",-1)])]),_:1}),n[20]||(n[20]=s(" 校对：",-1)),t(i,{href:"https://github.com/wxy"},{default:e(()=>[...n[16]||(n[16]=[s("wxy",-1)])]),_:1})]),a("p",null,[n[23]||(n[23]=s("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...n[21]||(n[21]=[s("LCTT",-1)])]),_:1}),n[24]||(n[24]=s(" 原创编译，",-1)),t(i,{href:"https://linux.cn/"},{default:e(()=>[...n[22]||(n[22]=[s("Linux中国",-1)])]),_:1}),n[25]||(n[25]=s(" 荣誉推出",-1))])])}const x=p(r,[["render",c]]);export{y as __pageData,x as default};
